model:
rachana: 1
sutra: us-company
version: 1
description: 
match: { kind: us-company, priority: 10 }
title: { pill: "US equities · Company", id: "$.TICKER", with: "$.NAME" }
strip:
  - { label: "Ticker", bind: "$.TICKER", emphasis: true }
  - { label: "Industry (SIC)", bind: "$.SIC_DESCRIPTION" }
  - { label: "Fiscal year", bind: "$.FISCAL_YEAR" }
  - { label: "Revenue", bind: "$.REVENUE", fmt: "compact" }
  - { label: "Net income", bind: "$.NET_INCOME", fmt: "compact", tone: "sign" }
  - { label: "Net margin", bind: "$.REVENUE ? $.NET_INCOME / $.REVENUE * 100 : null", fmt: "margin1", tone: "sign" }
  - { label: "Revenue growth", bind: "first($.FINANCIALS[?@.YEAR == $.FISCAL_YEAR - 1]).REVENUE ? ($.REVENUE - first($.FINANCIALS[?@.YEAR == $.FISCAL_YEAR - 1]).REVENUE) / abs(first($.FINANCIALS[?@.YEAR == $.FISCAL_YEAR - 1]).REVENUE) * 100 : null", fmt: "growth1", tone: "sign" }
  - { label: "Diluted EPS", bind: "$.EPS_DILUTED", fmt: "price2" }
panels:
  - id: financials-chart
    kind: area
    title: "Revenue and net income, USD"
    key: "F2"
    rows: "$.FINANCIALS"
    x: "YEAR"
    unit: "USD"
    series: [{ label: "Revenue", value: "REVENUE", tone: "link" }, { label: "Net income", value: "NET_INCOME", tone: "pos" }]
  - id: financials
    kind: table
    title: "Annual financials (10-K, USD)"
    key: "F3"
    rows: "$.FINANCIALS"
    search: false
    columns:
      - { label: "Fiscal year", bind: "@.YEAR" }
      - { label: "Period end", bind: "@.PERIOD_END", fmt: "date" }
      - { label: "Revenue", bind: "@.REVENUE", fmt: "compact" }
      - { label: "Net income", bind: "@.NET_INCOME", fmt: "compact", tone: "sign" }
      - { label: "Net margin", bind: "@.REVENUE ? @.NET_INCOME / @.REVENUE * 100 : null", fmt: "margin1", tone: "sign" }
      - { label: "Total assets", bind: "@.ASSETS", fmt: "compact" }
      - { label: "Total liabilities", bind: "@.LIABILITIES", fmt: "compact" }
      - { label: "Equity", bind: "@.EQUITY", fmt: "compact" }
      - { label: "Diluted EPS", bind: "@.EPS_DILUTED", fmt: "price2" }
  - id: filings
    kind: table
    title: "Recent SEC filings (a click opens one beside)"
    key: "F4"
    code: "FIL"
    rows: "$.FILINGS"
    empty: "No filings"
    columns:
      - { label: "Filed", bind: "@.FILED", fmt: "date" }
      - { label: "Form", bind: "@.FORM" }
      - { label: "What it is", bind: "@.DESCRIPTION" }
      - { label: "Report date", bind: "@.REPORT_DATE" }
      - { label: "Accession", bind: "@.ACCESSION" }
  - id: held-by-funds
    kind: table
    title: "Held by funds (a fund opens its page)"
    key: "F8"
    code: "HLD"
    area: "funds"
    rows: "$src.HOLDERS"
    empty: "No fund of the funds pack holds this company (or the pack is off)"
    columns:
      - { label: "Fund", bind: "link(@.FUND, 'fund', @.FUND_NAME)" }
      - { label: "Type", bind: "@.TYPE" }
      - { label: "Weight in the fund", bind: "@.PCT", fmt: "amount2" }
      - { label: "Value", bind: "@.VALUE", fmt: "compact", total: true }
      - { label: "Shares", bind: "@.SHARES", fmt: "compact", total: true }
      - { label: "Report date", bind: "@.REPORT_DATE", fmt: "date" }
  - id: fund-ownership
    kind: kv
    title: "Fund ownership"
    area: "funds"
    columns:
      - { label: "Funds holding it", bind: "link($src.TICKER, 'fund-holder', fmt($src.FUNDS, 'amount0') + ' of the 200 largest')" }
      - { label: "of which ETFs", bind: "$src.ETFS", fmt: "amount0" }
      - { label: "Value held", bind: "$src.TOTAL_VALUE", fmt: "compact" }
      - { label: "Share of its shares (%)", bind: "$src.PCT_OF_SHARES", fmt: "amount2" }
      - { label: "Average weight in a fund (%)", bind: "$src.AVG_WEIGHT", fmt: "amount2" }
      - { label: "Largest holder", bind: "link($src.TOP_HOLDER, 'fund', $src.TOP_HOLDER)" }
  - id: card
    kind: kv
    title: "Key facts"
    code: "CO"
    area: right
    columns:
      - { label: "Company", bind: "link($.TICKER, 'us-company', $.NAME)" }
      - { label: "Exchange", bind: "$.EXCHANGE" }
      - { label: "Listing", bind: "$.LISTING" }
      - { label: "SIC", bind: "link($.SIC, 'sic-sector', $.SIC + ' · ' + $.SIC_DESCRIPTION)" }
      - { label: "Division", bind: "$.SECTOR" }
      - { label: "Indexes", bind: "$.INDEX_TEXT" }
      - { label: "Fiscal year", bind: "$.FISCAL_YEAR" }
      - { label: "Revenue", bind: "$.REVENUE", fmt: "compact" }
      - { label: "Net income", bind: "$.NET_INCOME", fmt: "compact", tone: "sign" }
      - { label: "Net margin", bind: "$.REVENUE ? $.NET_INCOME / $.REVENUE * 100 : null", fmt: "margin1", tone: "sign" }
      - { label: "Diluted EPS (USD)", bind: "$.EPS_DILUTED", fmt: "price2" }
      - { label: "Shares outstanding", bind: "$.SHARES_OUTSTANDING", fmt: "compact" }
      - { label: "CIK", bind: "$.CIK" }
      - { label: "LEI", bind: "link($.LEI, 'lei-entity', $.LEI)" }
      - { label: "Incorporated in", bind: "$.STATE_OF_INCORPORATION" }
      - { label: "Fiscal year end (MM-DD)", bind: "$.FISCAL_YEAR_END" }
      - { label: "Reporting currency", bind: "$.CURRENCY" }
      - { label: "Headquarters", bind: "nonblank($.HEADQUARTERS, $.BUSINESS_ADDRESS)" }
      - { label: "Founded", bind: "$.FOUNDED" }
      - { label: "Website", bind: "$.WEBSITE" }
  - id: indexes
    kind: table
    title: "Index memberships"
    area: right
    rows: "$.INDEXES"
    search: false
    empty: "Not a member of the Dow 30, the Nasdaq-100, the S&P 500 or a bank list"
    columns:
      - { label: "Index", bind: "link(@.INDEX, 'index-membership', @.NAME)" }
      - { label: "Member since", bind: "@.SINCE", fmt: "date" }
  - id: note
    kind: markdown
    title: "About this page"
    area: right
    phone: { tier: "more", from: "fragment" }
    text: "Public data. The company, its SIC industry and its filings come from SEC EDGAR (public domain); the financials are the annual values of its 10-K XBRL filings (a foreign bank's 20-F or 40-F, in the currency it reports in, under key facts), a fiscal year being the calendar year its period ends in. Index membership, headquarters and founding come from Wikidata (CC0), the LEI from GLEIF (CC0). No index weights, no GICS and no prices: the price history (F6) is read live, off as shipped, for internal use only."
  - id: source
    kind: kv
    title: "Data source and licence"
    area: right
    phone: { tier: "must", from: "fragment" }
    rows: "$.PROVENANCE"
  - id: built
    kind: provenance
    title: "How this view was built"
    phone: { tier: "more", from: "fragment" }
  - id: refs
    kind: links
    title: "Linked entities"
    code: "REFS"
    area: right
    phone: { tier: "more", from: "fragment" }
keys: { F5: "link($.LEI, 'lei-entity', 'LEI record')", F6: "link($.PRICE_HISTORY, 'price-history')", F7: "link($.SIC_SECTOR, 'sic-sector')", F9: "raw" }
